41	            Self::ModelLengthExceeded {
42	                total_tokens,
43	                max_model_len,
44	            } => write!(
45	                formatter,
46	                "request total tokens {total_tokens} exceed max_model_len {max_model_len}"
47	            ),
48	            Self::WholePrefillExceedsStepBudget {
49	                prompt_tokens,
50	                max_num_batched_tokens,
51	            } => write!(
52	                formatter,
53	                "whole prefill has {prompt_tokens} tokens but max_num_batched_tokens is {max_num_batched_tokens}"
54	            ),
55	        }
