611	    #[test]
612	    fn impossible_and_duplicate_requests_are_rejected() {
613	        let mut whole = WorkerState::new(scheduler(2, 4, 8, PrefillPolicy::Whole)).unwrap();
614	        assert_eq!(
615	            whole.submit(request(1, 7, 2)).unwrap(),
616	            SubmissionResult::Rejected(RequestRejection::ModelLengthExceeded {
617	                total_tokens: 9,
