624	                prompt_tokens: 5,
625	                max_num_batched_tokens: 4,
626	            })
627	        );
628	        assert_eq!(
629	            whole.submit(request(3, 1, 1)).unwrap(),
630	            SubmissionResult::Queued
631	        );
632	        assert!(whole.submit(request(3, 1, 1)).is_err());
633	        assert_eq!(
