200	/// Cumulative prefix-cache lookups, in tokens.
201	///
202	/// The scheduler holds running totals; the bridge converts them to per-send
203	/// deltas before they reach Prometheus (see `StatsTracker`).
204	///
205	/// Both counters are token-granular, and the external family exists only for a
206	/// request whose connector was consulted — mirroring vLLM, which registers
207	/// `connector_prefix_cache_queries` as the prompt minus the local hits, so a
208	/// locally cached token never inflates the external denominator.
209	#[derive(Default, Clone, Copy)]
210	struct PrefixCacheTally {
211	    /// Prompt tokens looked up in the prefix cache.
212	    queries: u64,
213	    /// Looked-up tokens found in local KV.
214	    hits: u64,
215	    /// `queries - hits`: the part of the prompt a connector could serve.
216	    external_queries: u64,
217	    /// Of that remainder, how many the connector actually restored.
218	    external_hits: u64,
219	}
220	
221	impl PrefixCacheTally {
222	    /// The engine-contract snapshot. `hits` there counts every tier, so the
223	    /// externally restored tokens join the local ones. Like the qwen3 engine
224	    /// it mimics, the sim's connector cannot name the tier that answered, so
225	    /// its restores are `external_unspecified` rather than `host`.
226	    fn counters(&self) -> PrefixCacheCounters {
227	        PrefixCacheCounters {
228	            queries: self.queries,
229	            hits: self.hits + self.external_hits,
230	            host_queries: self.external_queries,
231	            external_unspecified_hits: self.external_hits,
232	            ..PrefixCacheCounters::default()
233	        }
234	    }
235	
236	    /// Tally one admitted request's prefix lookup.
237	    ///
238	    /// `knob` is the simulated lookup: `(local hits, externally restored hits)`.
239	    /// `None` means no prefix cache is configured, so nothing ran and nothing
240	    /// is counted — the counters must not invent lookups that never happened.
241	    ///
242	    /// Prompt scoring is skipped too: it forwards the prompt whole, matching
243	    /// the qwen3 executor's gate.
244	    fn note(&mut self, knob: Option<(usize, usize)>, request: &Request) {
245	        let Some((local_hits, external_hits)) = knob else {
246	            return;
247	        };
248	        if request.prompt_logprobs.is_some() {
249	            return;
250	        }
251	        let prompt = request.prompt_tokens.len();
252	        let local = local_hits.min(prompt);
253	        let external = external_hits.min(prompt - local);
254	        self.queries += prompt as u64;
255	        self.hits += local as u64;
256	        self.external_queries += (prompt - local) as u64;
257	        self.external_hits += external as u64;
258	    }
259	}
