619	impl Scheduler for SimScheduler {
620	    fn submit(&mut self, request: QueuedRequest) {
621	        self.queued.push(request);
622	    }
623	
624	    fn step(&mut self, ledger: &mut RequestLedger) -> Result<()> {
625	        if self.profiled.is_some() {
626	            let mut profiled = self
627	                .profiled
628	                .take()
629	                .expect("profiled runtime presence was checked above");
630	            let result = profiled.step(
631	                &self.config,
632	                &mut self.queued,
633	                ledger,
634	                &mut self.spec_decode,
635	                &mut self.prefix_cache,
636	            );
637	            self.profiled = Some(profiled);
638	            return result;
639	        }
640	        self.step_legacy(ledger)
641	    }
642	
643	    fn metrics(&self) -> SchedulerMetrics {
644	        if let Some(profiled) = &self.profiled {
645	            // The profiled lane drives its own run state, but the prefix-cache
646	            // counters are tallied on admission whichever lane admits the
647	            // request, so both lanes report them the same way.
648	            let mut metrics = profiled.metrics(self.spec_decode.as_ref());
649	            metrics.prefix_cache = self.prefix_cache_counters();
650	            return metrics;
651	        }
652	        SchedulerMetrics {
653	            num_running_reqs: self.running.len() as u64,
654	            num_waiting_reqs: self.queued.len() as u64,
655	            spec_decode: self.spec_decode,
656	            prefix_cache: self.prefix_cache_counters(),
657	            ..SchedulerMetrics::default()
658	        }
659	    }
660	}
